sys_atf_step.inputs:
(function(outputs, steps, stepResult) {
  var gate = new x_fed_day2_ops.EntraHelpdeskGate();
  // Simulate the confirming re-read failing (non-2xx / READ_FAILED).
  var verdict = gate.verify({ action: 'disableUser', userId: 'test-user-0001', _forceReadFailure: true });
  if (verdict && verdict.ok) {
    stepResult.setFailed('verify reported ok despite a failed confirming read - closure would be unproven');
    return;
  }
  stepResult.setSuccess();
})(outputs, steps, stepResult);
